package com.bank.clearing;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.NoSuchElementException;

// A FIFO queue implemented using two LIFO stacks.
public class ChequeQueue<T> {

    private final Deque<T> inbox = new ArrayDeque<>();   // newest on top
    private final Deque<T> outbox = new ArrayDeque<>();  // oldest on top

    // Enqueue is always O(1): just push onto the inbox.
    public void enqueue(T item) {
        inbox.push(item);
    }

    // Dequeue serves the oldest element in amortized O(1).
    public T dequeue() {
        shiftIfNeeded();
        if (outbox.isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return outbox.pop();
    }

    // Peek at the oldest element without removing it.
    public T peek() {
        shiftIfNeeded();
        if (outbox.isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return outbox.peek();
    }

    public boolean isEmpty() {
        return inbox.isEmpty() && outbox.isEmpty();
    }

    // Transfer inbox into outbox ONLY when outbox is empty.
    // This reverses the order so the oldest ends up on top.
    private void shiftIfNeeded() {
        if (outbox.isEmpty()) {
            while (!inbox.isEmpty()) {
                outbox.push(inbox.pop());
            }
        }
    }
}
