package com.bank.clearing;

import java.util.logging.Logger;

// Processes cheques strictly in arrival order using the FIFO queue.
public class ChequeClearingService {

    private static final Logger log = Logger.getLogger(ChequeClearingService.class.getName());
    private final ChequeQueue<String> queue = new ChequeQueue<>();

    public void submit(String chequeId) {
        queue.enqueue(chequeId);
        log.info(() -> "Cheque submitted for clearing: " + chequeId);
    }

    public void clearNext() {
        if (queue.isEmpty()) {
            log.warning("No cheques to clear");
            return;
        }
        String cleared = queue.dequeue();
        log.info(() -> "Cheque CLEARED (oldest first): " + cleared);
    }
}
