package com.bank.clearing;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ChequeQueueDemo {

    private static final Logger log = Logger.getLogger(ChequeQueueDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Cheque Clearing (FIFO via two stacks)");
        ChequeClearingService service = new ChequeClearingService();

        service.submit("CHQ-001");
        service.submit("CHQ-002");
        service.submit("CHQ-003");
        service.clearNext();          // clears CHQ-001 (triggers flip)
        service.submit("CHQ-004");
        service.clearNext();          // clears CHQ-002 (no flip, outbox has items)
        service.clearNext();          // clears CHQ-003
        service.clearNext();          // clears CHQ-004 (flip again)
    }
}
